def load() -> pd.DataFrame:
    df1 = pd.read_csv('data/environment/input/water-body-testing-2007.csv')
    df2 = pd.read_csv('data/environment/input/water-body-testing-2008.csv')
    df3 = pd.read_csv('data/environment/input/water-body-testing-2009.csv')
    return pd.concat([df1, df2, df3], ignore_index=True)

def process(summer_water_data):
    fresh = summer_water_data[summer_water_data['Beach Type Description'] == 'Fresh'].copy()

    result = []
    for region in ['Boston', 'Chatham', 'Amherst', 'Ashburnham']:
        for year in [2007, 2008, 2009]:
            for month in [6, 7, 8]:
                region_year_month = fresh[(fresh['Community'] == region) | 
                                          (fresh['County Description'].str.contains(region, na=False))]
                region_year_month = region_year_month[(region_year_month['Year'] == year) & 
                                                       (region_year_month['Month'] == month)]

                if len(region_year_month) > 0:
                    total_samples = len(region_year_month)
                    violations = (region_year_month['Violation'] == 'yes').sum()
                    exceedance_rate = violations / total_samples if total_samples > 0 else 0
                    result.append({
                        'Region': region,
                        'Year': year,
                        'Month': month,
                        'Exceedance_Rate': exceedance_rate,
                        'Total_Samples': total_samples,
                        'Violations': violations
                    })

    return pd.DataFrame(result)

def process(freshwater_merged):
    import pandas as pd

    # Calculate correlation between rainfall and exceedance rate for freshwater
    correlation = freshwater_merged['Rainfall'].corr(freshwater_merged['Exceedance_Rate'])

    # Return a simple dataframe with the result
    return pd.DataFrame({
        'Beach_Type': ['Freshwater'],
        'Correlation': [correlation]
    })

