def process(verify_results):
    result = verify_results.copy()
    result['abs_correlation'] = result['Correlation'].abs()
    higher_corr = result.loc[result['abs_correlation'].idxmax()]
    return pd.DataFrame({
        'Answer': [higher_corr['Beach_Type']],
        'Freshwater_Correlation': [result[result['Beach_Type'] == 'Freshwater']['Correlation'].values[0]],
        'Marine_Correlation': [result[result['Beach_Type'] == 'Marine']['Correlation'].values[0]]
    })

def process(verify_results):
    fw = verify_results[verify_results['Beach_Type'] == 'Freshwater']['Correlation'].values[0]
    marine = verify_results[verify_results['Beach_Type'] == 'Marine']['Correlation'].values[0]

    abs_fw = abs(fw)
    abs_marine = abs(marine)

    result_data = {
        'Beach_Type': ['Freshwater', 'Marine'],
        'Correlation': [fw, marine],
        'Absolute_Correlation': [abs_fw, abs_marine],
        'Higher_Correlation': ['Freshwater' if abs_fw > abs_marine else 'Marine'] * 2
    }

    return pd.DataFrame(result_data)
